"""Portable synthetic fixture generated by the original MATLAB call path."""

from pathlib import Path

import numpy as np
from scipy.io import loadmat

from multiscale import (canonical_band_objective_and_grad, canonical_band_value,
                        canonical_opt_dds_mruns, iss2dd, opt_gd_ddx_mruns, prepare_var,
                        trfun2dd, trfun2ddgrad, opt_gd_dds_mruns,
                        tsdata_to_var, tsdata_to_varmo, fit_var_auto,
                        run_grid_parallel, opt_es_dd, opt_es_dd_mruns,
                        run_full_dd, es_parms)
from multiscale.model import orthonormalise


F = loadmat(Path(__file__).parent / "fixtures" / "matlab_canonical.mat",
            simplify_cells=True)
ES = loadmat(Path(__file__).parent / "fixtures" / "matlab_temporal_es.mat",
             simplify_cells=True)


def _projector_error(left, right):
    return np.linalg.norm(left @ left.T-right @ right.T)


def test_model_transform_and_transfer_function():
    ass, c, k, cak, h, freqs = prepare_var(F["VARA"], F["V"], F["fs"], F["fres"])
    for observed, expected in ((ass, F["ASS"]), (c, F["C"]), (k, F["K"]),
                               (cak, F["CAK"]), (h, F["H"]), (freqs, F["freqs"])):
        np.testing.assert_allclose(observed, expected, atol=1e-13, rtol=1e-12)


def test_temporal_qz_matches_matlab():
    actual = iss2dd(F["Lfinal"][:, :, 0], F["ASS"], F["C"], F["K"])
    assert abs(actual-F["ddtime"]) < 1e-11


def test_temporal_dare_recovers_from_ill_conditioned_state_coordinates():
    a, c, k = F["ASS"], F["C"], F["K"]
    scale = np.diag(10.0**np.linspace(-6, 6, a.shape[0]))
    transformed_a = np.linalg.solve(scale, a @ scale)
    transformed_c = c @ scale
    transformed_k = np.linalg.solve(scale, k)
    value, diagnostics = iss2dd(F["Lfinal"][:, :, 0], transformed_a,
                                transformed_c, transformed_k,
                                return_diagnostics=True)
    assert diagnostics["method"] == "covariance_balanced"
    assert diagnostics["residual"] < 1e-8
    assert abs(value-F["ddtime"]) < 1e-11


def test_direct_state_space_es_matches_matlab_trajectory():
    np.testing.assert_allclose(
        es_parms(float(ES["rule"]), ES["L0"].shape[1] *
                 (ES["L0"].shape[0]-ES["L0"].shape[1])), ES["factors"], atol=1e-15)
    result = opt_es_dd(ES["A"], ES["C"], ES["K"], ES["L0"],
                       maxiters=int(ES["maxiters"]), sig=float(ES["sig0"]),
                       esrule=ES["factors"], tol=float(ES["tol"]),
                       mutations=ES["mutations"], history=True,
                       prebalance=False)
    assert abs(result.value-ES["dopt"]) < 1e-12
    assert result.iterations == ES["iters"]
    assert result.converged == ES["conv"]
    assert abs(result.step_size-ES["sig"]) < 1e-12
    np.testing.assert_allclose(result.history, ES["dhist"], atol=1e-12)
    assert _projector_error(result.basis, ES["Lopt"]) < 1e-12


def test_full_dd_pipeline_exposes_both_actual_methods():
    result = run_full_dd(F["VARA"], F["V"], int(F["fs"]), int(F["fres"]),
                         F["L0"], final_method="both", pre_iters=5,
                         spectral_iters=5, state_space_iters=5, seed=3)
    assert "pre" in result and "spectral" in result and "state_space" in result
    assert np.isfinite(result["spectral"].values).all()
    assert np.isfinite(result["state_space"].values).all()


def test_direct_state_space_es_parallel_matches_serial():
    kwargs = dict(a=F["ASS"], c=F["C"], k=F["K"], initial=F["L0"],
                  maxiters=7, seed=3)
    serial = opt_es_dd_mruns(**kwargs, workers=1)
    parallel = opt_es_dd_mruns(**kwargs, workers=2)
    np.testing.assert_allclose(serial.values, parallel.values, atol=1e-12)
    np.testing.assert_allclose(serial.bases, parallel.bases, atol=1e-12)


def test_canonical_gradient_is_derivative_of_value():
    l = orthonormalise(np.array([[1.0, 0.1], [0.2, 1.0], [0.3, -0.2]]))
    idx = np.asarray(F["idx"])-1
    value, grad, _, ok = canonical_band_objective_and_grad(l, F["H"], F["freqs"], idx)
    assert ok
    assert abs(value-canonical_band_value(l, F["H"], F["freqs"], idx)) < 1e-12
    tangent = np.array([[0.4, -0.2], [0.1, 0.3], [-0.2, 0.5]])
    tangent -= l @ (l.T @ tangent)
    tangent /= np.linalg.norm(tangent)
    eps = 1e-5
    plus = canonical_band_value(orthonormalise(l+eps*tangent), F["H"], F["freqs"], idx)
    minus = canonical_band_value(orthonormalise(l-eps*tangent), F["H"], F["freqs"], idx)
    assert abs((plus-minus)/(2*eps)-np.sum(grad*tangent)) < 1e-8


def test_two_optimisation_stages_match_matlab_values_and_subspaces():
    pre = opt_gd_ddx_mruns(F["CAK"], F["L0"], niters=80, history=True)
    np.testing.assert_allclose(pre.values, F["dpre"], atol=1e-12)
    for i in range(pre.bases.shape[2]):
        assert _projector_error(pre.bases[:, :, i], F["Lpre"][:, :, i]) < 1e-7
    final = canonical_opt_dds_mruns(F["H"], F["freqs"], np.asarray(F["idx"])-1,
                                      pre.bases, niters=80, history=True)
    np.testing.assert_allclose(final.values, F["dfinal"], atol=1e-12)
    for i in range(final.bases.shape[2]):
        assert _projector_error(final.bases[:, :, i], F["Lfinal"][:, :, i]) < 1e-5
    assert all(np.diff(h[:, 0]).max() <= 1e-12 for h in final.histories)


def test_original_integrated_spectral_path_matches_matlab():
    value, samples = trfun2dd(F["L0"][:, :, 0], F["H"])
    grad, magnitude = trfun2ddgrad(F["L0"][:, :, 0], F["H"])
    assert abs(value-F["di"]) < 1e-12
    np.testing.assert_allclose(samples, F["di_samples"], atol=1e-12)
    np.testing.assert_allclose(grad, F["gi"], atol=1e-12)
    assert abs(magnitude-F["gi_mag"]) < 1e-12
    result = opt_gd_dds_mruns(F["H"], F["Lpre"], niters=80, sig0=0.1,
                               tol=1e-10, history=True)
    np.testing.assert_allclose(result.values, F["dint"], atol=1e-12)
    for i in range(result.bases.shape[2]):
        assert _projector_error(result.bases[:, :, i], F["Lint"][:, :, i]) < 1e-5


def test_mvgc_lwr_fit_and_model_order_match_matlab():
    fit = tsdata_to_var(F["X"], 2)
    np.testing.assert_allclose(fit.coefficients, F["Afit"], atol=1e-12)
    np.testing.assert_allclose(fit.covariance, F["Vfit"], atol=1e-12)
    np.testing.assert_allclose(fit.residuals, F["Efit"], atol=1e-12)
    order = tsdata_to_varmo(F["X"], 4)
    assert (order.aic, order.bic, order.hqc, order.lrt) == (
        F["moaic"], F["mobic"], F["mohqc"], F["molrt"])
    for criterion in ("aic", "bic", "hqc"):
        np.testing.assert_allclose(getattr(order, criterion+"_curve"),
                                   F[criterion+"_curve"], atol=1e-9)


def test_all_four_model_order_choices_are_available():
    candidates = tsdata_to_varmo(F["X"], 4)
    for criterion in ("aic", "bic", "hqc", "lrt"):
        selected = fit_var_auto(F["X"], 4, criterion=criterion)
        assert selected.order == candidates.select(criterion)
        assert selected.fit.coefficients.shape[2] == selected.order
    assert candidates.select("LRT") == candidates.lrt


def test_mvgc_ols_fit_and_model_order_match_matlab():
    fit = tsdata_to_var(F["Xols"], 2, regmode="OLS")
    np.testing.assert_allclose(fit.coefficients, F["Aols"], atol=1e-12)
    np.testing.assert_allclose(fit.covariance, F["Vols"], atol=1e-12)
    np.testing.assert_allclose(fit.residuals, F["Eols"], atol=1e-12)
    order = tsdata_to_varmo(F["Xols"], 4, regmode="OLS")
    assert (order.aic, order.bic, order.hqc, order.lrt) == (
        F["oaic"], F["obic"], F["ohqc"], F["olrt"])
    for criterion in ("aic", "bic", "hqc"):
        np.testing.assert_allclose(getattr(order, criterion+"_curve"),
                                   F[criterion+"_ols"], atol=1e-12)


def test_parallel_grid_matches_serial_for_arbitrary_dimensions():
    kwargs = dict(a=F["VARA"], v=F["V"], fs=int(F["fs"]), fres=int(F["fres"]),
                  dimensions=(1, 2), bands={"low": (1, 4)}, runs=2, seed=7,
                  pre_iters=5, final_iters=5)
    serial = run_grid_parallel(**kwargs, workers=1)
    parallel = run_grid_parallel(**kwargs, workers=2)
    for key in serial:
        np.testing.assert_allclose(serial[key]["pre"].values,
                                   parallel[key]["pre"].values, atol=1e-12)
        np.testing.assert_allclose(serial[key]["final"].values,
                                   parallel[key]["final"].values, atol=1e-12)
